    protected function applyFix(\SplFileInfo $file, Tokens $tokens): void
    {
        $lineEnding = $this->lineEnding;

        $this->hasNewline = false;
        foreach ($tokens as $index => $token) {
            if ($token->isArray() && null !== $token->getId()) {
                if (($token->isWhitespace() || $token->isGivenKind(T_OPEN_TAG) || $token->isComment()) && str_contains($token->getContent(), "\n")) {
                    $this->hasNewline = true;

                    break;
                }
            } elseif ($this->getLineBreakCount($tokens, (int) $index, 1) > 0) {
                $this->hasNewline = true;

                break;
            }
        }

        // ignore one-line files
        if (!$this->hasNewline) {
            return;
        }

        $openTagIndex = $tokens->isMonolithicPhp() && $tokens[0]->isGivenKind(T_INLINE_HTML) ? 1 : 0;
        foreach ((new NamespacesAnalyzer())->getDeclarations($tokens) as $declaration) {
            if ($declaration->isGlobalNamespace() && $declaration->getStartIndex() === $declaration->getEndIndex()) {
                $openTagIndex = $declaration->getStartIndex();

                break;
            }
        }

        $token = $tokens[$openTagIndex];

        if (!str_contains($token->getContent(), "\n")) {
            $tokens[$openTagIndex] = new Token([$token->getId(), rtrim($token->getContent()).$lineEnding]);
        }

        $newLineIndex = $openTagIndex + 1;
        if (isset($tokens[$newLineIndex]) && !str_contains($tokens[$newLineIndex]->getContent(), "\n")) {
            if ($tokens[$newLineIndex]->isWhitespace()) {
                $tokens[$newLineIndex] = new Token([T_WHITESPACE, $lineEnding.$tokens[$newLineIndex]->getContent()]);
            } else {
                $tokens->insertAt($newLineIndex, new Token([T_WHITESPACE, $lineEnding]));
            }
        }
    }
}

